CREATE TABLE auth_users (id BINARY(16) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(150) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, failed_login_attempts INT NOT NULL DEFAULT 0, locked_until TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE auth_sessions (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, user_agent VARCHAR(500), ip_address VARCHAR(64), last_seen_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, INDEX idx_session_user(user_id), CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES auth_users(id));
CREATE TABLE refresh_tokens (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, session_id BINARY(16) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, INDEX idx_refresh_user(user_id), CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES auth_users(id), CONSTRAINT fk_refresh_session FOREIGN KEY(session_id) REFERENCES auth_sessions(id));
CREATE TABLE password_reset_tokens (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP(6) NOT NULL, used_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, INDEX idx_reset_user(user_id), CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES auth_users(id));
